def tilingRectangle(n, m):
    if n == m:
        return 1
    if n > m:
        n, m = m, n
    best = [n * m]
    h = [0] * m

    def dfs(cnt):
        if cnt >= best[0]:
            return
        mn = min(h)
        if mn == n:
            best[0] = cnt
            return
        start = h.index(mn)
        maxside = 0
        while start + maxside < m and h[start + maxside] == mn and mn + maxside + 1 <= n:
            maxside += 1
        for side in range(maxside, 0, -1):
            for k in range(side):
                h[start + k] += side
            dfs(cnt + 1)
            for k in range(side):
                h[start + k] -= side

    dfs(0)
    return best[0]
